fn frame(t: i32) {
    host::display::clear(0x000000);
    let cx: i32 = host::display::width() / 2;
    let cy: i32 = host::display::height() / 2;
    let r: i32 = 120;
    let mut i: i32 = 0;
    while i < 6 {
        let a0: i32 = t + (i * 256) / 6;
        let a1: i32 = t + ((i + 1) * 256) / 6;
        let x0: i32 = cx + (r * host::math::cos(a0)) / 256;
        let y0: i32 = cy + (r * host::math::sin(a0)) / 256;
        let x1: i32 = cx + (r * host::math::cos(a1)) / 256;
        let y1: i32 = cy + (r * host::math::sin(a1)) / 256;
        let col: i32 = if (i & 1) == 0 { 0x66ccff } else { 0xffffff };
        host::display::draw_line(x0, y0, x1, y1, col);
        host::display::fill_rect(x0 - 2, y0 - 2, 5, 5, 0xffcc33);
        i = i + 1;
    }
    let mut k: i32 = 0;
    while k < 3 {
        let b0: i32 = (0 - t) / 2 + (k * 256) / 3;
        let b1: i32 = (0 - t) / 2 + ((k + 1) * 256) / 3;
        let x0: i32 = cx + (55 * host::math::cos(b0)) / 256;
        let y0: i32 = cy + (55 * host::math::sin(b0)) / 256;
        let x1: i32 = cx + (55 * host::math::cos(b1)) / 256;
        let y1: i32 = cy + (55 * host::math::sin(b1)) / 256;
        host::display::draw_line(x0, y0, x1, y1, 0x888888);
        k = k + 1;
    }
    host::display::present();
}
